/**
 * @suppress
 */
public object FfiConverterTypeKasaClient: FfiConverter<KasaClient, Long> {
    override fun lower(value: KasaClient): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): KasaClient {
        return KasaClient(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): KasaClient {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: KasaClient) = 8UL

    override fun write(value: KasaClient, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



